                ]
            rows.append(d)
        distributions.append(rows)

    P = [
        [
            math.fsum(
                w[k] * distributions[k][level_index][r]
                for k in range(n_scenarios)
            )
            for r in range(n_receptors + 1)
        ]
        for level_index in range(4)
    ]

    Q: list[list[list[int]]] = []
    for quantile in qs:
        row: list[list[int]] = []
        for level_index in range(4):
            if quantile == 0.0:
                chosen = 0
            else:
