                    if (
                        math.fsum(P[level_index][s] for s in range(r + 1))
                        >= quantile
                    ):
                        chosen = r
                        break
            row.append(
                [1 if r == chosen else 0 for r in range(n_receptors + 1)]
            )
        Q.append(row)

    return Q

